import math

def wrap(a):
    return (a+180.0)%360.0-180.0

phase='rev'
fwd_dist=0.0
theta_f=None
n=0

def clamp(x,a):
    return max(-a,min(a,x))

def best_dir(cam, h):
    pts=[]
    for b,d in cam.get('walls',[]):
        pts.append((d*math.cos(math.radians(b)), d*math.sin(math.radians(b))))
    tdir=180.0-h
    best=None; bs=-1e9
    for k in range(-20,21):
        th=tdir+3*k
        c=math.cos(math.radians(th)); s=math.sin(math.radians(th))
        free=9.0
        for dx,dy in pts:
            f=dx*c+dy*s
            l=-dx*s+dy*c
            if f>0 and abs(l)<1.1:
                free=min(free,f)
        sc=free-0.03*abs(3*k)
        if sc>bs:
            bs=sc; best=th
    return best

def control(obs):
    global phase,fwd_dist,theta_f,n
    n+=1
    h=obs.get('hitch_deg',0.0)
    dt=obs.get('dt',0.1)
    v=obs['motion']['v_mps']
    look=-23
    if phase=='fwd':
        fwd_dist+=max(0.0,v)*dt
        if fwd_dist>2.5 or abs(h)<6:
            phase='rev'
        else:
            return (clamp(-0.5*h,34), 0.8, look)
    if abs(h)>36:
        phase='fwd'; fwd_dist=0.0
        return (0.0, 0.8, look)
    views=obs.get('views') or {}
    cam=views.get('camera')
    tgt=obs.get('target') or {}
    rig=obs['rig']
    rear=rig['trailer_rear']
    th=None
    if tgt.get('in_sight') and tgt.get('dist_m') is not None and tgt['dist_m']>0:
        eye=rig['eye']
        b=math.radians(tgt['bearing_deg']); d=tgt['dist_m']
        px=eye[0]+d*math.cos(b); py=eye[1]+d*math.sin(b)
        th=math.degrees(math.atan2(py-rear[1], px-rear[0]))
    elif cam is not None:
        th=best_dir(cam,h)
    if th is not None:
        if theta_f is None:
            theta_f=th
        else:
            theta_f=wrap(theta_f+0.3*wrap(th-theta_f))
    tdir=180.0-h
    e=wrap(theta_f-tdir) if theta_f is not None else 0.0
    hd=clamp(0.8*e,25.0)
    steer=clamp(0.75*h+1.5*(h-hd),34.0)
    if n%20==0:
        print('t=%.1f h=%.1f hd=%.1f th=%s steer=%.1f' % (obs['t'],h,hd,None if theta_f is None else round(theta_f,1),steer))
    return (steer,-0.8,look)

