dist=0.0
done=False
n=0
def control(obs):
    global phase,yaw,dist,done,n
    n+=1
    dt=obs.get('dt',0.1)
    v=obs['motion']['v_mps']
    st=obs.get('steer_deg',0.0)
    yaw+=math.degrees(v*math.tan(math.radians(st))/2.75)*dt
    dist+=abs(v)*dt
    h=obs.get('hitch_deg',0.0)
    look=0
    views=obs.get('views') or {}
    # safety: near rail at front
    danger=False
    for key in ('direct','periphery'):
        vw=views.get(key)
        if not vw: continue
        ox,oy=vw['origin']
        for b,d in vw.get('walls',[]):
            x=ox+d*math.cos(math.radians(b)); y=oy+d*math.sin(math.radians(b))
            if x>2.6 and x<4.4 and abs(y)<0.925+0.45:
                danger=True
    if n%10==0:
        print('t=%.1f ph=%s yaw=%.1f dist=%.2f h=%.1f st=%.1f danger=%s'%(obs['t'],phase,yaw,dist,h,st,danger))
    if done:
        return (0.0,0.0,look)
    if danger or abs(h)>40 or dist>4.5:
        done=True
        wake('forward stop: danger=%s yaw=%.1f h=%.1f dist=%.2f'%(danger,yaw,h,dist))
        return (st,0.0,look)
    if phase=='A':
        if yaw>=22.0:
            phase='B'
        else:
            return (34.0,0.5,look)
    if phase=='B':
        if yaw<=16.0 and st<-5:
            done=True
            wake('S done yaw=%.1f h=%.1f dist=%.2f'%(yaw,h,dist))
            return (0.0,0.0,look)
        return (-34.0,0.5,look)
    return (0.0,0.0,look)

